style.css:
@-moz-document domain("youtube.com") {
/* GLOBAL TRANSITION - Makes all your hovers smooth */
button, .yt-spec-button-shape-next {
    transition: all 0.2s ease-in-out !important;
}

/* 1. RED SUBSCRIBE BUTTON */
button[aria-label*="Subscribe"], 
.yt-spec-button-shape-next--filled.yt-spec-button-shape-next--mono {
    background-color: #ff0000 !important;
    color: #ffffff !important;
}
button[aria-label*="Subscribe"]:hover, 
.yt-spec-button-shape-next--filled.yt-spec-button-shape-next--mono:hover {
    background-color: #ff4d4d !important;
    box-shadow: 0 0 15px rgba(255, 0, 0, 0.6) !important;
}

/* 2. BLUE LIKE BUTTON */
.yt-spec-button-shape-next--tonal,
[aria-label*="like this video"] {
    background-color: #00a2ff !important;
}
.yt-spec-button-shape-next--tonal *,
[aria-label*="like this video"] * {
    color: #ffffff !important;
    fill: #ffffff !important;
}
/* Active/Pressed State */
.yt-spec-button-shape-next--filled.yt-spec-button-shape-next--call-to-action {
    background-color: #00e5ff !important;
}
/* Hover State */
.yt-spec-button-shape-next--tonal:hover,
[aria-label*="like this video"]:hover {
    background-color: #33bbff !important;
    box-shadow: 0 0 15px rgba(0, 162, 255, 0.6) !important;
}

/* 3. GREEN SHARE BUTTON */
[aria-label*="Share"], 
button[aria-label="Share"] {
    background-color: #228b22 !important;
    color: #ffffff !important;
}
[aria-label*="Share"] *,
button[aria-label="Share"] * {
    color: #ffffff !important;
    fill: #ffffff !important;
}
[aria-label*="Share"]:hover,
button[aria-label="Share"]:hover {
    background-color: #32cd32 !important;
    box-shadow: 0 0 15px rgba(50, 205, 50, 0.6) !important;
}

/* 4. ORANGE & BLUE ASK BUTTON */
[aria-label^="Ask"] {
    background-color: #0088ff !important;
    border: 2px solid #ff8c00 !important;
}
[aria-label^="Ask"]:hover {
    background-color: #3389ff !important; /* Your Spring Green tweak */
    border-color: #f78b00 !important;
    box-shadow: 0 0 15px #f78b00 !important;
}

/* 5. SEARCH BAR */
#container.ytd-searchbox {
    background-color: #111 !important;
    border: 1px solid #333 !important;
}
#container.ytd-searchbox:hover {
    border: 1px solid #0088ff !important;
    box-shadow: 0 0 8px rgba(0, 136, 255, 0.3) !important;
}
}
